ALTER TABLE t MODIFY TTL d + INTERVAL 1 DAY;

ALTER TABLE t MODIFY TTL d + toIntervalDay(1) WHERE s = 'a' AND b = 'c';

ALTER TABLE t MODIFY TTL d + INTERVAL 1 DAY DELETE WHERE s = 'a';

ALTER TABLE t MODIFY TTL d + INTERVAL 1 DAY TO DISK 'cold', d + INTERVAL 2 DAY DELETE;

ALTER TABLE t ON CLUSTER c MODIFY TTL d + INTERVAL 1 DAY TO VOLUME 'slow';

ALTER TABLE t MODIFY TTL d + INTERVAL 1 MONTH GROUP BY k;

ALTER TABLE t MODIFY TTL d + INTERVAL 1 DAY SETTINGS mutations_sync = 2;
